catalog_script_client.script:
      function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    var ga = new GlideAjax('sn_lg_ops.DateUtilsAjax');
    ga.addParam('sysparm_name', 'dateInPast');
    ga.addParam('date', newValue);
    ga.getXML(validateDates);

    function validateDates(response) {
        var difference = response.responseXML.documentElement.getAttribute("answer");
        if (difference == 'true') {
            g_form.addErrorMessage(getMessage('Contract start date must be later than today.'));
            g_form.setValue('start_date', '');
        } else {
            var end_date = g_form.getValue('end_date');
            if (end_date) {
                var startDate = new Date(newValue);
                var endDate = new Date(end_date);
                if (endDate < startDate) {
                    g_form.addErrorMessage(getMessage('Contract start date must be earlier than the Contract end date.'));
                    g_form.setValue('start_date', '');
                }
            }
        }
    }
}
